function applyCoupon(cart, code, now = new Date()) {
	const { round2 } = require('../util/money');
	const { subtotal } = require('../cart/totals');
	const coupon = loadCoupons().find(c => c.code.toUpperCase() === String(code || '').toUpperCase());
	if (!coupon) throw new Error('INVALID_COUPON');
	const day = now.toISOString().slice(0, 10);
	if (day > coupon.expires) throw new Error('EXPIRED_COUPON');
	const sub = subtotal(cart);
	return round2(coupon.type === 'percent' ? (sub * coupon.value) / 100 : Math.min(coupon.value, sub));
}

module.exports = { COUPONS_FILE, loadCoupons, applyCoupon };
